if (!defined('ABSPATH')) exit;
final class WPSX {
 const OPT='wpsx_settings'; const BASE='wpsx_baseline'; const EVENTS='wpsx_events'; const CRON='wpsx_scan_event';
 static function defaults(){return ['monitor'=>1,'login_limit'=>1,'uploads_guard'=>0,'core_repair'=>0,'quarantine'=>0,'firewall'=>1,'max_attempts'=>5,'lock_minutes'=>30,'email_alerts'=>1,'backup_retention'=>3,'auto_repair'=>0,'two_factor'=>0,'db_audit'=>1,'strict_firewall'=>0,'auto_quarantine'=>0];}
 static function cfg(){return wp_parse_args(get_option(self::OPT,[]),self::defaults());}
 static function path(){return dirname(ABSPATH).'/wpsx-private';}
 static function log($type,$message,$level='info'){$events=get_option(self::EVENTS,[]); if(!is_array($events))$events=[]; array_unshift($events,['time'=>time(),'type'=>sanitize_key($type),'message'=>sanitize_text_field($message),'level'=>sanitize_key($level)]);update_option(self::EVENTS,array_slice($events,0,250),false);if($level==='critical' && !empty(self::cfg()['email_alerts'])){ $key='wpsx_alert_'.md5($type.$message);if(!get_transient($key)){set_transient($key,1,HOUR_IN_SECONDS);wp_mail(get_option('admin_email'),'[WP Sentinel X] Security alert',$message);}}}
 static function init(){add_action('admin_menu',[__CLASS__,'menu'],5);add_action('admin_init',[__CLASS__,'actions']);add_action(self::CRON,[__CLASS__,'scan']);add_filter('authenticate',[__CLASS__,'auth'],99,3);add_action('wp_login_failed',[__CLASS__,'failed']);add_action('wp_login',[__CLASS__,'success'],10,2);add_filter('wp_handle_upload_prefilter',[__CLASS__,'upload']);add_filter('xmlrpc_enabled',function(){return false;});add_action('user_register',function($id){self::log('user','New user #'.intval($id));});add_action('set_user_role',function($id,$role){self::log('role','User #'.intval($id).' role: '.$role,'warning');},10,2);add_action('activated_plugin',function($p){self::log('plugin','Activated: '.$p);});add_action('deactivated_plugin',function($p){self::log('plugin','Deactivated: '.$p);});add_action('upgrader_process_complete',function(){delete_option(self::BASE);self::log('update','WordPress update completed; baseline reset');},10,0);add_action('init',[__CLASS__,'early_rules'],1);add_action('admin_init',[__CLASS__,'database_audit']);}
 static function activate(){self::private_dir();if(!wp_next_scheduled(self::CRON))wp_schedule_event(time()+300,'hourly',self::CRON);self::log('system','WP Sentinel X activated');}
 static function deactivate(){wp_clear_scheduled_hook(self::CRON);}
 static function private_dir(){ $p=self::path();if(!is_dir($p))wp_mkdir_p($p); if(is_dir($p)){@file_put_contents($p.'/index.php','<?php // Silence');@file_put_contents($p.'/.htaccess',"Deny from all\nRequire all denied\n");@file_put_contents($p.'/web.config','<configuration><system.webServer><security><authorization><deny users="*" /></authorization></security></system.webServer></configuration>');}}
 static function admin(){return current_user_can('manage_options');}
 static function menu(){add_menu_page('WP Sentinel X','Sentinel X','manage_options','wpsx',[__CLASS__,'page'],'dashicons-shield-alt',75);}
 static function nonce(){check_admin_referer('wpsx_action');if(!self::admin())wp_die('Not authorized');}
 static function actions(){if(empty($_POST['wpsx_action']))return;self::nonce();$action=sanitize_key(wp_unslash($_POST['wpsx_action']));$notice='Action completed.';
 if($action==='settings'){$c=self::cfg();foreach(['monitor','login_limit','uploads_guard','core_repair','quarantine','firewall','email_alerts','auto_repair','two_factor','db_audit','strict_firewall','auto_quarantine'] as $k)$c[$k]=isset($_POST[$k])?1:0;$c['auto_quarantine']=0;$c['auto_repair']=0;$c['two_factor']=0;foreach(['max_attempts','lock_minutes','backup_retention'] as $k)$c[$k]=max(1,min(100,(int)($_POST[$k]??$c[$k])));update_option(self::OPT,$c,false);self::log('settings','Settings updated');$notice='Settings saved.';}
 elseif($action==='scan'){$result=self::scan();$notice='Scan complete: '.intval($result['issues']).' issue(s).';}
 elseif($action==='guard'){$result=self::guard_uploads();$notice=$result?'Apache upload guard installed. Verify with your host.':'Guard not installed: unsupported or unwritable path.';}
 elseif($action==='backup'){$notice='Local database exports are disabled until an offsite encrypted backup and verified restore workflow is implemented.';self::log('backup','Unsafe local database export attempt blocked','warning');}
 elseif($action==='repair'){$file=isset($_POST['file'])?sanitize_text_field(wp_unslash($_POST['file'])):'';$result=self::repair($file);$notice=is_wp_error($result)?$result->get_error_message():'Verified core file restored.';}
 elseif($action==='quarantine_file'){$file=isset($_POST['file'])?sanitize_text_field(wp_unslash($_POST['file'])):'';$result=self::quarantine_file($file);$notice=is_wp_error($result)?$result->get_error_message():'File quarantined.';}
 set_transient('wpsx_notice_'.get_current_user_id(),$notice,60);wp_safe_redirect(admin_url('admin.php?page=wpsx'));exit;}
 static function early_rules(){if(empty(self::cfg()['firewall']))return; $uri=$_SERVER['REQUEST_URI']??''; $decoded=rawurldecode($uri); if(preg_match('~(?:^|/)(?:\.env|\.git/|wp-config\.php|composer\.(?:json|lock))(?:[/?]|$)~i',$decoded)){status_header(403);exit('Forbidden');}if(!empty(self::cfg()['strict_firewall'])){ $query=(string)($_SERVER['QUERY_STRING']??''); if(strlen($query)>8192 || preg_match('~(?:\.\./|%2e%2e%2f|<script|%3cscript|union(?:\s|%20)+select)~i',$query)){self::log('firewall','Blocked suspicious query from '.self::ip(),'warning');status_header(403);exit('Forbidden');}}}
 static function ip(){ $ip=$_SERVER['REMOTE_ADDR']??'';return filter_var($ip,FILTER_VALIDATE_IP)?$ip:'unknown';}
 static function auth($user,$username,$password){if(empty(self::cfg()['login_limit'])||$username==='')return $user;$key='wpsx_lock_'.md5(strtolower($username).'|'.self::ip());if(get_transient($key))return new WP_Error('wpsx_locked','Too many login attempts. Please try again later.');return $user;}
 static function failed($username){if(empty(self::cfg()['login_limit']))return;$key='wpsx_attempts_'.md5(strtolower($username).'|'.self::ip());$n=(int)get_transient($key)+1;set_transient($key,$n,HOUR_IN_SECONDS);if($n>=self::cfg()['max_attempts']){set_transient('wpsx_lock_'.md5(strtolower($username).'|'.self::ip()),1,self::cfg()['lock_minutes']*MINUTE_IN_SECONDS);self::log('login','Login lockout for '.sanitize_user($username),'warning');}}
 static function success($login,$user){delete_transient('wpsx_attempts_'.md5(strtolower($login).'|'.self::ip()));self::log('login','Login: '.sanitize_user($login));}
 static function upload($file){$ext=strtolower(pathinfo($file['name']??'',PATHINFO_EXTENSION));$deny=['php','phtml','phar','php3','php4','php5','php7','php8','cgi','pl','py','sh','htaccess','user.ini'];if(in_array($ext,$deny,true))$file['error']='Executable files are blocked by WP Sentinel X.';return $file;}
 static function guard_uploads(){if(empty(self::cfg()['uploads_guard']))return false;$u=wp_upload_dir();if(!empty($u['error']))return false;$base=$u['basedir'];if(!is_dir($base)||!is_writable($base))return false;$target=$base.'/.htaccess';if(file_exists($target)&&strpos((string)@file_get_contents($target),'WPSX PHP GUARD')===false)return false;$rules="# WPSX PHP GUARD\n<FilesMatch \"\\.(php[0-9]?|phtml|phar)$\">\nRequire all denied\n</FilesMatch>\n";return false!==@file_put_contents($target,$rules,LOCK_EX);}
 static function core_files(){require_once ABSPATH.'wp-admin/includes/update.php';$locale=get_locale();$checks=get_core_checksums($GLOBALS['wp_version'],$locale);if(!is_array($checks))$checks=get_core_checksums($GLOBALS['wp_version'],'en_US');return is_array($checks)?$checks:new WP_Error('checksums','Unable to retrieve official WordPress checksums.');}
 static function scan(){if(empty(self::cfg()['monitor']))return ['issues'=>0];$checks=self::core_files();if(is_wp_error($checks)){self::log('scan',$checks->get_error_message(),'warning');return ['issues'=>0];}$issues=[];foreach($checks as $relative=>$md5){$file=ABSPATH.$relative;if(!is_file($file)||!hash_equals(strtolower($md5),strtolower((string)@md5_file($file))))$issues[]=['file'=>$relative,'type'=>'core_mismatch'];} $known=get_option(self::BASE,[]);$snap=[];$dirs=[WP_CONTENT_DIR.'/mu-plugins',WP_CONTENT_DIR.'/plugins',WP_CONTENT_DIR.'/themes',wp_upload_dir()['basedir']];$count=0;foreach($dirs as $dir){if(!is_dir($dir))continue;try{$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($dir,FilesystemIterator::SKIP_DOTS));foreach($it as $f){if(++$count>30000)break 2;if(!$f->isFile()||$f->getSize()>8*1024*1024)continue;$p=$f->getPathname();if(!preg_match('/\.(php|phtml|phar)$/i',$p))continue;$rel=str_replace(ABSPATH,'',$p);$hash=@hash_file('sha256',$p);if(!$hash)continue;$snap[$rel]=$hash;if(isset($known[$rel])&&!hash_equals($known[$rel],$hash))$issues[]=['file'=>$rel,'type'=>'changed_php'];if(!isset($known[$rel])&&$known)$issues[]=['file'=>$rel,'type'=>'new_php'];}}catch(Throwable $e){self::log('scan','Directory scan error: '.$e->getMessage(),'warning');}}
 if(!$known)self::log('scan','Initial PHP baseline recorded; verify site is clean first','warning');if(!$known)update_option(self::BASE,$snap,false);update_option('wpsx_issues',$issues,false);update_option('wpsx_last_scan',time(),false);if($issues)self::log('scan',count($issues).' file integrity issue(s) detected','critical');/* Automatic repair intentionally disabled pending integration and rollback tests. */return ['issues'=>count($issues)];}
 static function safe_core($relative){$checks=self::core_files();if(is_wp_error($checks)||!isset($checks[$relative]))return new WP_Error('notcore','Not a verified core path.');$base=realpath(ABSPATH);$full=ABSPATH.$relative;$parent=realpath(dirname($full));if(!$base||!$parent||($parent!==$base&&strpos($parent,$base.DIRECTORY_SEPARATOR)!==0)||is_link($full))return new WP_Error('path','Unsafe file path.');return $checks[$relative];}
 static function repair($relative){$md5=self::safe_core($relative);if(is_wp_error($md5))return $md5;$locale=get_locale();$version=$GLOBALS['wp_version'];$url='https://core.svn.wordpress.org/tags/'.rawurlencode($version).'/'.implode('/',array_map('rawurlencode',explode('/',$relative)));$res=wp_safe_remote_get($url,['timeout'=>25,'limit_response_size'=>5*1024*1024]);if(is_wp_error($res)||wp_remote_retrieve_response_code($res)!==200)return new WP_Error('download','Could not download official file.');$body=wp_remote_retrieve_body($res);if(!hash_equals(strtolower($md5),md5($body)))return new WP_Error('verify','Downloaded content failed checksum verification.');$dest=ABSPATH.$relative;if(!is_writable(dirname($dest)))return new WP_Error('permissions','Directory not writable.');self::private_dir();if(!is_dir(self::path()) || !is_writable(self::path()))return new WP_Error('backup','Private backup location unavailable; repair aborted.');$archive=self::path().'/core-'.gmdate('Ymd-His').'-'.wp_generate_password(8,false).'.bak';if(is_file($dest)&&!@copy($dest,$archive))return new WP_Error('backup','Could not preserve old file.');$temp=@tempnam(dirname($dest),'.wpsx-');if($temp===false)return new WP_Error('write','Unable to allocate temporary repair file.');if(@file_put_contents($temp,$body,LOCK_EX)!==strlen($body)||!hash_equals(strtolower($md5),md5_file($temp))){@unlink($temp);return new WP_Error('verify','Temporary repair file failed verification.');}if(is_file($dest))@chmod($temp,fileperms($dest)&0777);if(!@rename($temp,$dest)){@unlink($temp);return new WP_Error('write','Atomic replacement failed; original file was preserved.');}if(!hash_equals(strtolower($md5),md5_file($dest))){if(is_file($archive))@copy($archive,$dest);return new WP_Error('verify','Post-repair verification failed; rollback attempted.');}self::log('repair','Restored verified core file: '.$relative,'warning');return true;}
 static function quarantine_file($relative){$root=realpath(WP_CONTENT_DIR);$full=realpath(ABSPATH.$relative);if(!$root||!$full||strpos($full,$root.DIRECTORY_SEPARATOR)!==0||is_link($full)||!is_file($full))return new WP_Error('path','Only regular wp-content files may be quarantined.');self::private_dir();$dest=self::path().'/quarantine-'.gmdate('Ymd-His').'-'.wp_generate_password(12,false).'.dat';if(!@rename($full,$dest))return new WP_Error('move','Unable to quarantine file.');self::log('quarantine','Quarantined: '.$relative,'critical');return true;}
 static function backup(){return new WP_Error('disabled','Local database exports are disabled: webroot storage is not reliably private.');}
 static function legacy_backup_disabled(){global $wpdb;self::private_dir();if(!class_exists('ZipArchive'))return new WP_Error('zip','ZipArchive required for backups.');$filename=self::path().'/db-'.gmdate('Ymd-His').'-'.wp_generate_password(10,false).'.sql.zip';$zip=new ZipArchive();if($zip->open($filename,ZipArchive::CREATE)!==true)return new WP_Error('zip','Could not create backup.');$sql="-- WP Sentinel X database backup\n";$tables=$wpdb->get_col('SHOW TABLES');foreach($tables as $table){$table=(string)$table;if(!preg_match('/^[a-zA-Z0-9_]+$/',$table))continue;$create=$wpdb->get_row('SHOW CREATE TABLE `'.$table.'`',ARRAY_N);if($create)$sql.="\nDROP TABLE IF EXISTS `{$table}`;\n{$create[1]};\n";$offset=0;do{$rows=$wpdb->get_results('SELECT * FROM `'.$table.'` LIMIT '.intval($offset).', 200',ARRAY_A);foreach($rows as $row){$values=array_map(function($v)use($wpdb){return $v===null?'NULL':"'".esc_sql((string)$v)."'";},array_values($row));$sql.='INSERT INTO `'.$table.'` VALUES ('.implode(',',$values).');' ."\n";} $offset+=200;if(strlen($sql)>100*1024*1024){$zip->close();@unlink($filename);return new WP_Error('size','Backup exceeds 100MB safety limit.');}}while(count($rows)===200);} $zip->addFromString('database.sql',$sql);$zip->close();self::log('backup','Database backup created');return true;}
 static function prune_backups(){ $files=glob(self::path().'/db-*.sql.zip');if(!$files)return;usort($files,function($a,$b){return filemtime($b)<=>filemtime($a);});foreach(array_slice($files,max(1,(int)self::cfg()['backup_retention'])) as $file)@unlink($file);}
 static function database_audit(){if(empty(self::cfg()['db_audit'])||!self::admin()||get_transient('wpsx_db_audit_done'))return;set_transient('wpsx_db_audit_done',1,DAY_IN_SECONDS);$admins=get_users(['role'=>'administrator','fields'=>['ID','user_login','user_registered']]);$ids=array_map(function($u){return (int)$u->ID;},$admins);sort($ids);$previous=get_option('wpsx_admin_ids',null);if(is_array($previous) && $previous!==$ids)self::log('database','Administrator account membership changed; review users immediately','critical');update_option('wpsx_admin_ids',$ids,false);}
 static function base32_decode_secret($s){$alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';$s=strtoupper(preg_replace('/[^A-Z2-7]/i','',$s));$bits='';for($i=0;$i<strlen($s);$i++){ $pos=strpos($alphabet,$s[$i]);if($pos===false)return false;$bits.=str_pad(decbin($pos),5,'0',STR_PAD_LEFT);} $out='';foreach(str_split($bits,8) as $b){if(strlen($b)===8)$out.=chr(bindec($b));}return $out;}
 static function totp($secret,$counter){$key=self::base32_decode_secret($secret);if(!$key)return ''; $bin=pack('N2',floor($counter/4294967296),$counter%4294967296);$hash=hash_hmac('sha1',$bin,$key,true);$offset=ord(substr($hash,-1))&15;$n=(unpack('N',substr($hash,$offset,4))[1]&0x7fffffff)%1000000;return str_pad((string)$n,6,'0',STR_PAD_LEFT);}
 static function login_totp_field(){if(empty(self::cfg()['two_factor']))return;echo '<p><label for="wpsx_totp">Authenticator code (if enrolled)</label><input type="text" name="wpsx_totp" id="wpsx_totp" class="input" inputmode="numeric" autocomplete="one-time-code" maxlength="6"></p>';}
 static function verify_totp($user,$username,$password){if(empty(self::cfg()['two_factor'])||is_wp_error($user)||!($user instanceof WP_User)||!user_can($user,'manage_options'))return $user;$secret=get_user_meta($user->ID,'wpsx_totp_secret',true);if(!$secret)return $user;$code=isset($_POST['wpsx_totp'])?preg_replace('/[^0-9]/','',wp_unslash($_POST['wpsx_totp'])):'';if(strlen($code)!==6)return new WP_Error('wpsx_2fa','Authenticator code required.');$now=(int)floor(time()/30);for($i=-1;$i<=1;$i++)if(hash_equals(self::totp($secret,$now+$i),$code))return $user;self::log('2fa','Invalid authenticator code for '.sanitize_user($username),'warning');return new WP_Error('wpsx_2fa','Invalid authenticator code.');}
 static function two_factor_profile($user){if(!current_user_can('edit_user',$user->ID)||!user_can($user,'manage_options'))return;$enrolled=(bool)get_user_meta($user->ID,'wpsx_totp_secret',true);echo '<h2>WP Sentinel X — Authenticator</h2><table class="form-table"><tr><th>TOTP status</th><td>'.($enrolled?'Enrolled':'Not enrolled').'<p>To enroll, enter a Base32 secret generated in a trusted authenticator app or password manager and add the same secret to that app. Keep a recovery admin account before enabling enforcement.</p><input type="text" name="wpsx_new_totp_secret" autocomplete="off" placeholder="Base32 secret (min 16 chars)" style="width:320px"><p><label><input type="checkbox" name="wpsx_remove_totp" value="1"> Remove existing enrollment</label></p></td></tr></table>';}
 static function save_two_factor($user_id){if(!current_user_can('edit_user',$user_id)||!user_can($user_id,'manage_options'))return;if(!empty($_POST['wpsx_remove_totp'])){delete_user_meta($user_id,'wpsx_totp_secret');self::log('2fa','Administrator TOTP enrollment removed','warning');return;}$s=isset($_POST['wpsx_new_totp_secret'])?strtoupper(preg_replace('/[^A-Z2-7]/i','',wp_unslash($_POST['wpsx_new_totp_secret']))):'';if(strlen($s)>=16 && self::base32_decode_secret($s)!==false){update_user_meta($user_id,'wpsx_totp_secret',$s);self::log('2fa','Administrator TOTP enrolled');}}
 static function diagnostics(){
  $uploads=wp_upload_dir();$root=realpath(ABSPATH);$private=realpath(dirname(ABSPATH));
  return ['PHP version'=>PHP_VERSION,'WordPress version'=>get_bloginfo('version'),
    'Private backup location'=>($private && $root && strpos($private.DIRECTORY_SEPARATOR,$root.DIRECTORY_SEPARATOR)!==0)?'Outside document root (verify hosting mapping)':'Requires verification',
    'Uploads writable'=>(empty($uploads['error']) && is_writable($uploads['basedir']))?'Yes':'No / error',
    'Server'=>sanitize_text_field($_SERVER['SERVER_SOFTWARE']??'Unknown'),
    'Scheduled scan'=>wp_next_scheduled(self::CRON)?'Scheduled (traffic dependent)':'Not scheduled',
    'Core checksum access'=>is_wp_error(self::core_files())?'Unavailable':'Available',
    'Automatic repair'=>'Disabled pending staging tests',
    'Offsite backups'=>'Not configured'];
 }
 static function post($action,$label,$extra=[]){echo '<form method="post" style="display:inline-block;margin:3px">';wp_nonce_field('wpsx_action');echo '<input type="hidden" name="wpsx_action" value="'.esc_attr($action).'">';foreach($extra as $k=>$v)echo '<input type="hidden" name="'.esc_attr($k).'" value="'.esc_attr($v).'">';submit_button($label,'secondary','submit',false);echo '</form>';}
 static function page(){if(!self::admin())return;$c=self::cfg();$issues=get_option('wpsx_issues',[]);$events=get_option(self::EVENTS,[]);echo '<div class="wrap"><h1>🛡 WP Sentinel X <small>v0.6.3</small></h1><p><strong>Important:</strong> This is an early security build. Test on staging and keep independent backups. No plugin can guarantee complete protection.</p>';$notice=get_transient('wpsx_notice_'.get_current_user_id());if($notice){echo '<div class="notice notice-info"><p>'.esc_html($notice).'</p></div>';delete_transient('wpsx_notice_'.get_current_user_id());}echo '<div style="display:flex;gap:16px;flex-wrap:wrap">';foreach(['Last scan'=>($t=get_option('wpsx_last_scan'))?wp_date('Y-m-d H:i',$t):'Never','Issues'=>count($issues),'PHP baseline'=>count(get_option(self::BASE,[])),'Events'=>count($events)] as $label=>$value)echo '<div style="background:#fff;padding:18px;min-width:160px;border:1px solid #ddd"><strong>'.esc_html($label).'</strong><h2>'.esc_html((string)$value).'</h2></div>';echo '</div><h2>Actions</h2>';self::post('scan','Run integrity scan');self::post('guard','Install Apache upload PHP guard');echo '<p><strong>Note:</strong> 2FA requires individual enrollment on user profile; automatic quarantine is intentionally not active. Offsite backup and server write locks require host integration.</p><h2>Settings</h2><form method="post">';wp_nonce_field('wpsx_action');echo '<input type="hidden" name="wpsx_action" value="settings"><table class="form-table">';$labels=['monitor'=>'Hourly core and PHP file monitoring','login_limit'=>'Login attempt rate limiting','uploads_guard'=>'Enable Apache uploads PHP execution guard (requires install button)','core_repair'=>'Allow manual verified core repair (automatic repair disabled in this build)','quarantine'=>'Allow manual quarantine (automatic quarantine disabled in this build)','firewall'=>'Block sensitive file URL requests','email_alerts'=>'Email critical security alerts','auto_repair'=>'Automatic repair unavailable until verified staging tests','two_factor'=>'Require TOTP for administrators who have enrolled a secret','db_audit'=>'Audit administrator accounts daily','strict_firewall'=>'Block suspicious query patterns (may cause false positives)','auto_quarantine'=>'Automatic quarantine (reserved: disabled until validated)'];foreach($labels as $k=>$label){echo '<tr><th>'.esc_html($label).'</th><td><label><input type="checkbox" name="'.esc_attr($k).'" value="1" '.checked(!empty($c[$k]),true,false).'></label></td></tr>';}foreach(['max_attempts'=>'Max failed login attempts','lock_minutes'=>'Lockout duration (minutes)','backup_retention'=>'Number of local database backups to retain'] as $k=>$label)echo '<tr><th>'.esc_html($label).'</th><td><input type="number" min="1" max="100" name="'.esc_attr($k).'" value="'.esc_attr($c[$k]).'"></td></tr>';echo '</table>';submit_button('Save settings');echo '</form><h2>Integrity issues</h2><p>Never repair or quarantine files without a verified backup and review. Plugin/theme changes may be legitimate.</p><table class="widefat striped"><thead><tr><th>File</th><th>Type</th><th>Action</th></tr></thead><tbody>';foreach(array_slice($issues,0,100) as $item){echo '<tr><td><code>'.esc_html($item['file']).'</code></td><td>'.esc_html($item['type']).'</td><td>';if($item['type']==='core_mismatch'&&!empty($c['core_repair']))self::post('repair','Restore verified core',['file'=>$item['file']]);if($item['type']!=='core_mismatch'&&!empty($c['quarantine']))self::post('quarantine_file','Quarantine',['file'=>$item['file']]);echo '</td></tr>';}if(!$issues)echo '<tr><td colspan="3">No reported issues (not proof of a clean site).</td></tr>';echo '</tbody></table><h2>Recent security events</h2><table class="widefat striped"><thead><tr><th>Time</th><th>Severity</th><th>Event</th></tr></thead><tbody>';foreach(array_slice($events,0,50) as $e)echo '<tr><td>'.esc_html(wp_date('Y-m-d H:i',$e['time'])).'</td><td>'.esc_html($e['level']).'</td><td>'.esc_html($e['message']).'</td></tr>';echo '</tbody></table><p>Server-level WAF, immutable filesystem policies, offsite backups, reliable 2FA, and malware signature intelligence require separate implementation/infrastructure.</p></div>';}
}
